"""Simple SQLModel ORM schema for Keywords dataclasses.
The schema keeps lists/dicts in JSON columns for simplicity. """ from sqlmodel import Field, SQLModel
class PageBase(SQLModel): id: str = Field(primary_key=True, index=True, max_length=36) creation_timestamp: float = Field(nullable=False) raw_text: str = Field(default="")

# setup_database.py
import sys
from backend.database.init_db import init_db  # Adjust the module path to match your structure

def main() -> None:
    try:
        init_db()
        print("Database schema initialized successfully.")
    except Exception as exc:
        print(f"Initialization failed: {exc}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

